#include "work_follow_through.hpp"
#include "work_execution_detail.hpp"
namespace hanmo::resident {namespace {
using namespace work_detail;
const WorkResultSource& result(const AcceptedWorkFollowThroughRef&r){return std::visit([](const auto&v)->const WorkResultSource&{return v.work_result_ref;},r);}
const SourceRef& obligation(const AcceptedWorkFollowThroughRef&r){if(const auto*p=std::get_if<OutcomeApplication>(&r))return p->original_application_ref;return std::get<ReportBack>(r).original_reporting_obligation_ref;}
bool real_result(const WorkResultSource&r){return std::visit([](const auto&v){using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,LegacyAppeaseWork>)return !v.work_completion_fact_id.empty();else return !v.fact_id.empty();},r);}
Status refs(const std::vector<SourceRef>&rs){for(std::size_t i=0;i<rs.size();++i){if(!valid(rs[i]))return common_failure("InvalidFollowThroughActualResult");for(std::size_t j=0;j<i;++j)if(same(rs[i],rs[j]))return common_failure("DuplicateFollowThroughActualResult");}return common_success();}
}
bool same_work_result_source(const WorkResultSource&a,const WorkResultSource&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if constexpr(std::is_same_v<T,LegacyAppeaseWork>)return x.work_completion_fact_id==y.work_completion_fact_id;else return x.fact_id==y.fact_id;},a);}
bool same_work_follow_through(const AcceptedWorkFollowThroughRef&a,const AcceptedWorkFollowThroughRef&b){if(a.index()!=b.index())return false;return std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;const auto&y=std::get<T>(b);if(x.task_id!=y.task_id||!same_work_result_source(x.work_result_ref,y.work_result_ref))return false;if constexpr(std::is_same_v<T,OutcomeApplication>)return x.objective_id==y.objective_id&&same(x.program_ref,y.program_ref)&&x.target_line_id==y.target_line_id&&x.application_kind==y.application_kind&&same(x.original_application_ref,y.original_application_ref);else return x.report_requirement_id==y.report_requirement_id&&same(x.report_content_ref,y.report_content_ref)&&same(x.original_reporting_obligation_ref,y.original_reporting_obligation_ref)&&same_registered_communication_address(x.addressee,y.addressee);},a);}
const SourceRef& work_follow_through_terminal_source(const WorkFollowThroughUnavailableSource&s){return std::visit([](const auto&v)->const SourceRef&{using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,ReportBackUnavailable>)return v.report_terminal_ref;else return v.application_terminal_ref;},s);}
Status validate_work_follow_through_query(const WorkFollowThroughQuery&q){auto terms=validate_terms_revision(q.accepted_terms_ref);if(!terms.ok)return terms;if(!valid(q.accepted_goal_ref)||!real_result(result(q.follow_through_ref))||std::holds_alternative<LegacyAppeaseWork>(result(q.follow_through_ref)))return common_failure("InvalidWorkFollowThroughQuery");return std::visit([&](const auto&v)->Status{if(v.task_id.empty())return common_failure("WorkFollowThroughTaskRequired");using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,OutcomeApplication>){if(v.objective_id.empty()||v.target_line_id.empty()||!valid(v.program_ref)||!valid(v.original_application_ref)||static_cast<Integer>(v.application_kind)<0||static_cast<Integer>(v.application_kind)>2)return common_failure("InvalidWorkOutcomeObligation");if((v.application_kind==WorkApplicationKind::patrol_security)!=std::holds_alternative<PatrolResult>(v.work_result_ref))return common_failure("WorkFollowThroughResultKindMismatch");return common_success();}else {if(v.report_requirement_id.empty()||!valid(v.report_content_ref)||!valid(v.original_reporting_obligation_ref))return common_failure("InvalidWorkReportObligation");return validate_registered_communication_address(v.addressee);}},q.follow_through_ref);}
Status validate_work_follow_through_result(const WorkFollowThroughQuery&q,const WorkFollowThroughReadResult&r){auto valid_query=validate_work_follow_through_query(q);if(!valid_query.ok)return valid_query;if(const auto*f=std::get_if<WorkFollowThroughFulfilled>(&r)){if(f->actual_result_refs.empty())return common_failure("FulfilledWorkObligationNeedsActualResults");return refs(f->actual_result_refs);}if(const auto*b=std::get_if<WorkFollowThroughTemporarilyBlocked>(&r))return valid(b->current_reason_source_ref)&&valid(b->continuity_source_ref)?common_success():common_failure("WorkTemporaryBlockNeedsActualSources");const auto&v=std::get<WorkFollowThroughPermanentlyUnfulfillable>(r);const auto&t=v.terminal;const auto&terminal_ref=work_follow_through_terminal_source(v.source);if(!valid(terminal_ref)||terminal_ref.id!=t.source_terminal_id||t.source_schema<=0||!same(t.original_obligation_ref,obligation(q.follow_through_ref))||!same(t.accepted_goal_ref,q.accepted_goal_ref)||!same_work_result_source(t.work_result_ref,result(q.follow_through_ref))||!valid(t.actual_cause_ref)||!valid(t.continuity_source_ref))return common_failure("WorkFollowThroughTerminalBindingMismatch");auto time=compare_world_moments(t.effective_game_time,t.effective_game_time);if(!time.ok)return {false,{},time.error};auto preserved=refs(t.preserved_actual_result_refs);if(!preserved.ok)return preserved;if(const auto*a=std::get_if<OutcomeApplication>(&q.follow_through_ref)){if(a->application_kind==WorkApplicationKind::patrol_security){const auto*p=std::get_if<PatrolApplicationUnavailable>(&v.source);if(!p||!same(p->program_ref,a->program_ref)||p->target_line_id!=a->target_line_id)return common_failure("PatrolApplicationTerminalMismatch");}else if(a->application_kind==WorkApplicationKind::production_improvement){const auto*p=std::get_if<ImprovementApplicationUnavailable>(&v.source);if(!p||p->work_ref.owner_domain.empty()||p->work_ref.work_id.empty())return common_failure("ImprovementApplicationTerminalMismatch");}else{const auto*p=std::get_if<FacilityApplicationUnavailable>(&v.source);if(!p||!valid(p->asset_ref))return common_failure("FacilityApplicationTerminalMismatch");}}else {const auto*p=std::get_if<ReportBackUnavailable>(&v.source);if(!p||!same(p->reporting_obligation_ref,std::get<ReportBack>(q.follow_through_ref).original_reporting_obligation_ref))return common_failure("ReportBackTerminalMismatch");}return common_success();}
}
